def _find_latest_profile(profile_dir: Path) -> Path | None:
    """Find most recent profile JSON in directory."""
    profiles = list(profile_dir.glob("*.json"))
    if not profiles:
        return None
    # Sort by modification time, newest first
    profiles.sort(key=lambda p: p.stat().st_mtime, reverse=True)
    return profiles[0]


def _classify_ladder_routes(topic: str) -> list[str]:
    """Classify topic into ladder route(s) based on keyword matching."""
    topic_lower = topic.lower()
    matched_routes = []
    route_scores = {}

    for route, keywords in ROUTE_KEYWORDS.items():
        score = sum(1 for kw in keywords if kw.lower() in topic_lower)
        if score > 0:
            route_scores[route] = score

    if not route_scores:
        # Default fallback for general business queries
        return ["western_bootstrap_saas"]

    # Return top 2 routes by score
    sorted_routes = sorted(route_scores.items(), key=lambda x: -x[1])
    return [r[0] for r in sorted_routes[:2]]


def _run_ladder(topic: str, routes: list[str], timeout_sec: int = 90) -> dict:
    """Run ladder-runner.py for non-Google research. Returns drill-recommended sources."""
    if not LADDER_RUNNER_PATH.exists() or not VENV_PYTHON.exists():
        return {
            "status": "unavailable",
            "error": "ladder-runner.py or venv not found",
            "routes_attempted": routes,
            "drill_sources": [],
        }

    all_drill_sources = []
    errors = []

    for route in routes:
        try:
            result = subprocess.run(
                [str(VENV_PYTHON), str(LADDER_RUNNER_PATH),
                 "--topic", topic, "--route", route, "--json"],
                capture_output=True,
                text=True,
                timeout=timeout_sec,
                cwd=LADDER_RUNNER_PATH.parent,
            )

            if result.returncode == 0 and result.stdout.strip():
                data = json.loads(result.stdout)
                drill_sources = data.get("summary", {}).get("drill_recommended_sources", [])
                for src in drill_sources:
                    src["route"] = route
                all_drill_sources.extend(drill_sources)
            else:
                errors.append(f"{route}: exit {result.returncode}")

        except subprocess.TimeoutExpired:
            errors.append(f"{route}: timeout after {timeout_sec}s")
        except json.JSONDecodeError as e:
            errors.append(f"{route}: JSON parse error: {e}")
        except Exception as e:
            errors.append(f"{route}: {type(e).__name__}: {e}")

    return {
        "status": "ok" if all_drill_sources else ("partial" if errors else "empty"),
        "routes_attempted": routes,
        "drill_sources": all_drill_sources,
        "drill_source_count": len(all_drill_sources),
        "errors": errors if errors else None,
    }

